    function [LOG_DEPTH-1:0] gray2bin;
        input [LOG_DEPTH-1:0] gray;
        begin
            gray2bin = gray;
            for (integer i = LOG_DEPTH-2; i >= 0; i = i - 1) begin
                gray2bin[i] = gray[i] ^ gray[i+1];
            end
        end
    endfunction

